    <title>Terms Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-muted: #f8fafc;
        --text: #162033;
        --text-muted: #52607a;
        --border: #d7deea;
        --border-strong: #8fa3c7;
        --accent: #315efb;
        --accent-strong: #2249d8;
        --shadow: 0 20px 50px rgba(22, 32, 51, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        margin: 0;
        min-height: 100%;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(49, 94, 251, 0.12), transparent 35%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      body {
        min-width: 320px;
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--text);
        color: #fff;
        transform: translateY(-200%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 2rem 1rem;
      }

      .consent-card {
        width: min(100%, 420px);
        padding: 2rem;
        background: var(--surface);
        border: 1px solid rgba(215, 222, 234, 0.9);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        padding: 0.35rem 0.7rem;
        border-radius: 999px;
        background: rgba(49, 94, 251, 0.08);
        color: var(--accent-strong);
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(1.75rem, 3vw, 2.2rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 1.5rem;
        color: var(--text-muted);
        line-height: 1.5;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: var(--surface-muted);
      }

      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 0.85rem;
      }

      input[type="checkbox"] {
        width: 1.15rem;
        height: 1.15rem;
        margin-top: 0.15rem;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      label {
        font-weight: 600;
        line-height: 1.4;
      }

      .helper-text {
        margin: 0.5rem 0 0 2rem;
        color: var(--text-muted);
        font-size: 0.95rem;
        line-height: 1.45;
      }

      .submit-button {
        border: 0;
        border-radius: 14px;
        padding: 0.95rem 1.2rem;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        cursor: pointer;
        transition:
          transform 0.18s ease,
          box-shadow 0.18s ease,
          background 0.18s ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 12px 24px rgba(49, 94, 251, 0.24);
      }

      .submit-button:focus-visible,
      input[type="checkbox"]:focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .submit-button:active {
        transform: translateY(0);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--accent-strong);
        font-weight: 600;
      }

      @media (max-width: 480px) {
        .consent-card {
          padding: 1.5rem;
        }

        .helper-text {
          margin-left: 0;
        }
      }

      @media (forced-colors: active) {
        .consent-card,
        .form-field {
          background: Canvas;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .eyebrow {
          background: Canvas;
          color: ButtonText;
          border: 1px solid ButtonBorder;
        }

        .submit-button {
          background: ButtonFace;
          color: ButtonText;
          border: 1px solid ButtonBorder;
        }

        .submit-button:focus-visible,
        input[type="checkbox"]:focus-visible,
        .skip-link:focus {
          outline-color: Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>
    <script>
      const FormField = ({ id, label, helperText }) => `
        <div class="form-field">
          <div class="checkbox-row">
            <input id="${id}" name="${id}" type="checkbox" required aria-describedby="${id}-hint" />
            <label for="${id}">${label}</label>
          </div>
          <p class="helper-text" id="${id}-hint">${helperText}</p>
        </div>
      `;

      const ConsentForm = () => `
        <form id="consent-form">
          ${FormField({
            id: "terms",
            label: "I agree to the Terms of Use",
            helperText: "Required to continue with your submission."
          })}
          <button class="submit-button" type="submit">Submit</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      `;

      const ConsentCard = () => `
        <main class="page-shell" id="main-content">
          <section class="consent-card" aria-labelledby="page-title">
            <span class="eyebrow">Quick consent</span>
            <h1 id="page-title">Review and confirm</h1>
            <p class="intro">Please accept the terms to continue with this product flow.</p>
            ${ConsentForm()}
          </section>
        </main>
      `;

      const App = () => ConsentCard();

      document.getElementById("root").innerHTML = App();

      document.getElementById("consent-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const checkbox = document.getElementById("terms");
        const status = document.getElementById("form-status");

        if (!checkbox.checkValidity()) {
          checkbox.reportValidity();
          checkbox.focus();
          status.textContent = "Please agree to the terms before submitting.";
          return;
        }

        status.textContent = "Consent submitted successfully.";
      });
    </script>
  </body>
</html>
